#include "tca/runtime.h"

template <typename T>
__device__ static __forceinline__ T Axpy3Combine0(T p0, T p1) {
  return (p0 + p1);
}

// Axpy3: launch 512 CTAs x 1024 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 128 B (v0: disjoint offsets, zero reuse)
namespace {

__global__ void __launch_bounds__(1024) Axpy3(uint32_t R, uint32_t C, uint32_t e4, const float* __restrict__ x, const float* __restrict__ z, float* __restrict__ out, float alpha, float beta, float gamma) {
  tca::rt::TensorView<const float, 3u> x_v(x, R, C, 4u);
  tca::rt::TensorView<const float, 3u> z_v(z, R, C, 4u);
  tca::rt::TensorView<float, 2u> out_v(out, R, C);
  // dynamic SMEM pool (128 B): one pool, disjoint v0 offsets — the future RA pass overlaps them
  extern __shared__ __align__(16) char tca_smem[];

  tca::rt::KernelInfo kinfo;
  // LNT #0: R=CTA(T=16,LoC=32) C=CTA(T=16,LoC=16) e4=thread/warp(T=16,LoC=32) dim=thread/warp(LoC=1024) dim=thread/warp(LoC=1024) e4=sequential(T=16,LoC=1)
  {
    // CTA-space mapping (absolute LoC per dim: 32u, 16u — the factorization this nest remaps)
    tca::rt::GridMapping grid_map0(kinfo, 2u, 32u, 16u);
    // per-CTA thread-space mapping (absolute warp counts K per dim: 32u)
    tca::rt::ThreadMapping thread_map1(kinfo, 1u, 32u);
    auto v0 = alpha;
    auto v1 = beta;
    auto c0 = 0.0f;
    auto v2 = gamma;
    auto c1 = 0u;
    auto v3 = R;
    auto c2 = 1u;
    auto v4 = C;
    auto c3 = 2u;
    auto v5 = 4u;
    auto v6 = grid_map0.index(0u);
    auto c4 = 16u;
    auto v7 = (v6 * c4);
    auto v8 = grid_map0.index(1u);
    auto v9 = (v8 * c4);
    auto v10 = thread_map1.index(0u);
    auto v11 = (v10 * c4);
    auto v12 = thread_map1.lane_id();
    auto v13 = (v12 + c2);
    auto v14 = (v13 * c2);
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c0, Axpy3Combine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 32u));
    // @R tile-between rounds — CTA, T=16, LoC=32 (map dim 0)
    for (auto R_it0 = tca::rt::CtaIterator(grid_map0, 0u, 32u, 0u, 512u, v3); R_it0.Has(); R_it0.Next()) {
      auto v15 = (v7 + R_it0.Index());
      auto v16 = tca::rt::umin(v15, v3);
      auto v17 = (v3 - v16);
      auto v18 = tca::rt::umin(c4, v17);
      // @C tile-between rounds — CTA, T=16, LoC=16 (map dim 1)
      for (auto C_it1 = tca::rt::CtaIterator(grid_map0, 1u, 16u, 0u, 256u, v4); C_it1.Has(); C_it1.Next()) {
        auto v19 = (v9 + C_it1.Index());
        auto v20 = tca::rt::umin(v19, v4);
        auto v21 = (v4 - v20);
        auto v22 = tca::rt::umin(c4, v21);
        // @R walk — sequential, LoC=1
        for (auto R_it2 = tca::rt::SeqIterator(0u, 1u, v18); R_it2.Has(); R_it2.Next()) {
          // @C walk — sequential, LoC=1
          for (auto C_it3 = tca::rt::SeqIterator(0u, 1u, v22); C_it3.Has(); C_it3.Next()) {
            // per-element bracket opens (argument-free; re-initializes from the construction-time init)
            reducer0.Init();
            // @e4 tile-between rounds — thread/warp, T=16, LoC=32 (map dim 0)
            for (auto e4_it4 = tca::rt::ThrIterator(thread_map1, 0u, 32u, 0u, 512u, v5); e4_it4.Has(); e4_it4.Next()) {
              auto v23 = (v11 + e4_it4.Index());
              auto v24 = tca::rt::umin(v23, v5);
              auto v25 = (v5 - v24);
              auto v26 = tca::rt::umin(c4, v25);
              auto v27 = tca::rt::umin(v14, v26);
              // @e4 inside walk (tile elements) — T=16
              for (auto e4_it5 = tca::rt::SeqIterator((v12 * c2), 1u, v27); e4_it5.Has(); e4_it5.Next()) {
                auto v28 = (v23 + e4_it5.Index());
                auto v29 = x_v.Get((v15 + R_it2.Index()), (v19 + C_it3.Index()), v28);
                auto v30 = (v0 * v29);
                auto v31 = z_v.Get((v15 + R_it2.Index()), (v19 + C_it3.Index()), v28);
                auto v32 = (v1 * v31);
                auto v33 = (v30 + v32);
                reducer0.Reduce(v33);
              }
            }
            // per-element combine — every participant receives the element's final value
            auto v34 = reducer0.Combine();
            auto v35 = tanhf(v34);
            auto v36 = (v2 * v35);
            auto v37 = (v34 + v36);
            // single-owner store — the element's owner thread writes (R2/R3)
            if (thread_map1.is_first_in_cta()) {
              out_v.Set(v37, (v15 + R_it2.Index()), (v19 + C_it3.Index()));
