}

}  // namespace

void Axpy3Launch(uint32_t e4, const tca::Tensor<float, 3u>& x, const tca::Tensor<float, 3u>& z, tca::Tensor<float, 2u>& out, float alpha, float beta, float gamma, cudaStream_t tca_stream) {
  const uint32_t R = x.Dim(0u);
  const uint32_t C = x.Dim(1u);
  TCA_REQUIRE(z.Dim(0u) == R, "z.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(z.Dim(1u) == C, "z.Dim(1) must equal C (dim C)");
  TCA_REQUIRE(out.Dim(0u) == R, "out.Dim(0) must equal R (dim R)");
  TCA_REQUIRE(out.Dim(1u) == C, "out.Dim(1) must equal C (dim C)");
  tca::rt::ValidateLaunch(dim3(512u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, 512u);
  Axpy3<<<dim3(512u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, tca_stream>>>(R, C, e4, x.Data(), z.Data(), out.Data(), alpha, beta, gamma);
  TCA_CUDA_CHECK(cudaGetLastError());
}
